package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.LRUMap;
import java.io.*;
import java.lang.reflect.*;
import java.math.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TypeFactory_constructSpecializedType_TriageGen2Test {

    private TypeFactory typeFactory;

    @Before
    public void setUp() {
        typeFactory = TypeFactory.defaultInstance();
    }

    @Test
    public void testOptimization_SameRawClass() {
        JavaType baseType = typeFactory.constructSimpleType(ArrayList.class, null);
        JavaType result = typeFactory.constructSpecializedType(baseType, ArrayList.class);
        assertSame("Should return same instance if raw class is identical", baseType, result);
    }

    @Test
    public void testFromObject_Subclass() {
        JavaType baseType = typeFactory.constructSimpleType(Object.class, null);
        JavaType result = typeFactory.constructSpecializedType(baseType, String.class);
        assertEquals(String.class, result.getRawClass());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testIncompatibleSubclass_ThrowsException() {
        JavaType baseType = typeFactory.constructSimpleType(Integer.class, null);
        // String is not a subtype of Integer
        typeFactory.constructSpecializedType(baseType, String.class);
    }

    @Test
    public void testNoGenericsInBaseType_ResolvesSubtype() {
        // baseType has no bindings (e.g., just List.class without <String>)
        JavaType baseType = typeFactory.constructSimpleType(List.class, null);
        JavaType result = typeFactory.constructSpecializedType(baseType, ArrayList.class);
        assertEquals(ArrayList.class, result.getRawClass());
        assertTrue(result.getBindings().isEmpty());
    }

    @Test
    public void testMapShortcut_HashMap() {
        JavaType baseType = typeFactory.constructMapType(Map.class, String.class, Integer.class);
        JavaType result = typeFactory.constructSpecializedType(baseType, HashMap.class);

        assertTrue(result instanceof MapType);
        assertEquals(HashMap.class, result.getRawClass());
        assertEquals(String.class, ((MapType) result).getKeyType().getRawClass());
        assertEquals(Integer.class, ((MapType) result).getContentType().getRawClass());
    }

    @Test
    public void testMapShortcut_TreeMap() {
        JavaType baseType = typeFactory.constructMapType(Map.class, String.class, Integer.class);
        JavaType result = typeFactory.constructSpecializedType(baseType, TreeMap.class);
        assertEquals(TreeMap.class, result.getRawClass());
    }

    @Test
    public void testMapShortcut_EnumMap() {
        JavaType baseType = typeFactory.constructMapType(Map.class, String.class, Integer.class);
        JavaType result = typeFactory.constructSpecializedType(baseType, EnumMap.class);
        assertEquals(EnumMap.class, result.getRawClass());
    }

    @Test
    public void testMapShortcut_LinkedHashMap() {
        JavaType baseType = typeFactory.constructMapType(Map.class, String.class, Integer.class);
        JavaType result = typeFactory.constructSpecializedType(baseType, LinkedHashMap.class);
        assertEquals(LinkedHashMap.class, result.getRawClass());
    }

    @Test
    public void testCollectionShortcut_ArrayList() {
        JavaType baseType = typeFactory.constructCollectionType(List.class, String.class);
        JavaType result = typeFactory.constructSpecializedType(baseType, ArrayList.class);

        assertTrue(result instanceof CollectionType);
        assertEquals(ArrayList.class, result.getRawClass());
        assertEquals(String.class, ((CollectionType) result).getContentType().getRawClass());
    }

    @Test
    public void testCollectionShortcut_LinkedList() {
        JavaType baseType = typeFactory.constructCollectionType(List.class, String.class);
        JavaType result = typeFactory.constructSpecializedType(baseType, LinkedList.class);
        assertEquals(LinkedList.class, result.getRawClass());
    }

    @Test
    public void testCollectionShortcut_HashSet() {
        JavaType baseType = typeFactory.constructCollectionType(Set.class, Integer.class);
        JavaType result = typeFactory.constructSpecializedType(baseType, HashSet.class);
        assertEquals(HashSet.class, result.getRawClass());
    }

    @Test
    public void testCollectionShortcut_TreeSet() {
        JavaType baseType = typeFactory.constructCollectionType(Set.class, Integer.class);
        JavaType result = typeFactory.constructSpecializedType(baseType, TreeSet.class);
        assertEquals(TreeSet.class, result.getRawClass());
    }

    @Test
    public void testEnumSet_Shortcut() {
        // EnumSet is special: if rawBase is EnumSet, return baseType
        JavaType baseType = typeFactory.constructCollectionType(EnumSet.class, Integer.class);
        JavaType result = typeFactory.constructSpecializedType(baseType, EnumSet.class);
        // The logic says: if (rawBase == EnumSet.class) return baseType;
        // Since we are passing EnumSet as subclass, and rawBase is EnumSet, it triggers optimization at start
        // But if we bypassed optimization, the EnumSet check is there.
        assertSame(baseType, result);
    }

    @Test
    public void testNoTypeParametersInSubclass() {
        // Subclass has 0 type parameters (e.g., Integer.class)
        JavaType baseType = typeFactory.constructCollectionType(List.class, String.class);
        JavaType result = typeFactory.constructSpecializedType(baseType, Integer.class);
        // This should fail the isAssignableFrom check first
        try {
            typeFactory.constructSpecializedType(baseType, Integer.class);
            fail("Should have thrown IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("not subtype of"));
        }
    }

    @Test
    public void testComplexResolution_Interface() {
        // Testing the 'baseType.isInterface()' branch
        // Create a generic interface type
        JavaType baseType = typeFactory.constructType(new com.fasterxml.jackson.databind.type.TypeReference<List<String>>() {});
        // Subclass is ArrayList (which implements List)
        JavaType result = typeFactory.constructSpecializedType(baseType, ArrayList.class);

        assertNotNull(result);
        assertEquals(ArrayList.class, result.getRawClass());
    }

    @Test
    public void testComplexResolution_NonInterface() {
        // Testing the 'else' branch for refine (baseType is not interface)
        // Use an abstract class
        abstract class Base implements Comparable<Base> {
            public abstract int compareTo(Base o);
        }
        class Derived extends Base {
            @Override public int compareTo(Base o) { return 0; }
        }

        JavaType baseType = typeFactory.constructSimpleType(Base.class, null);
        JavaType result = typeFactory.constructSpecializedType(baseType, Derived.class);

        assertEquals(Derived.class, result.getRawClass());
    }
}
